### 参考答案

可以用阶乘分块逐位确定排列。先把 1-based 的 `k` 减 1，转为 0-based；剩余 `m` 个数时，每个首位数字对应 `(m-1)!` 个排列，因此当前数字的索引是 `k / (m-1)!`。

```cpp
#include <string>
#include <vector>

class Solution {
public:
    std::string getPermutation(int n, int k) {
        std::vector<int> factorial(n, 1);
        for (int i = 1; i < n; ++i) {
            factorial[i] = factorial[i - 1] * i;
        }

        std::vector<int> numbers;
        for (int i = 1; i <= n; ++i) {
            numbers.push_back(i);
        }

        --k;  // 转成 0-based
        std::string result;

        for (int remaining = n; remaining >= 1; --remaining) {
            int blockSize = factorial[remaining - 1];
            int index = k / blockSize;

            result += char('0' + numbers[index]);
            numbers.erase(numbers.begin() + index);
            k %= blockSize;
        }

        return result;
    }
};
